"""Generated device module ``<app>/dtx_devices/`` for the devices of a draft.

Pure core module (no UI, no vendor terms). The module is plain C that an app can call without knowing the
devicetree:

* ``CMakeLists.txt``: ``target_include_directories`` / ``target_sources`` for the generated files,
* ``include/dtx_devices.h`` (umbrella) with ``dtx_devices_init()`` (``device_is_ready()`` of every device),
* ``include/dtx_<id>.h`` and ``src/dtx_<id>.c`` per device with a small typed API per class:
  sensor ``dtx_<id>_read(struct dtx_<id>_data *)`` (``sensor_sample_fetch`` / ``sensor_channel_get``),
  LED (child of ``gpio-leds``) ``dtx_<id>_set(bool)``, any other device ``dtx_<id>_get()``.

Rules (CONFIGURATOR.md, "Generated device module"): ``src/`` of the app is never touched; the only change
outside ``dtx_devices/`` is the one line ``add_subdirectory(dtx_devices)`` in the app's ``CMakeLists.txt``,
added by :func:`apply_cmake_line` after the caller has shown :attr:`GenPlan.cmake_diff` and asked the user.

Every generated file starts with one header line ``generated by dt_explorer ... checksum <hex>``. The checksum
covers the text after that line. A file whose checksum still matches is the tool's own and is regenerated; a
file that was edited (or has no header) is left alone and only a diff is reported (:attr:`GenFile.diff`).
Sensor channels come from the driver source (:func:`channels_from_driver`); the caller may change the list.
"""
from __future__ import annotations

import difflib
import hashlib
import logging
import re
from dataclasses import dataclass, field
from pathlib import Path
from string import Template

from .draft import Draft, DraftChild

log = logging.getLogger("dt_explorer.codegen")

MODULE_DIR = "dtx_devices"
CMAKE_LINE = "add_subdirectory(dtx_devices)"
TEMPLATES = Path(__file__).resolve().parent.parent / "codegen_templates"
_HEADER_RX = re.compile(r"^(?:/\*|#) generated by dt_explorer \(dtx_devices\), checksum ([0-9a-f]{16})\b")

#: Names after ``SENSOR_CHAN_`` that are no real measurement.
_NOT_CHANNELS = {"ALL", "MAX", "PRIV_START", "COMMON_COUNT"}
#: What the UI offers on top of the channels the driver names (common Zephyr channels).
COMMON_CHANNELS = ["SENSOR_CHAN_AMBIENT_TEMP", "SENSOR_CHAN_PRESS", "SENSOR_CHAN_HUMIDITY",
                   "SENSOR_CHAN_ACCEL_XYZ", "SENSOR_CHAN_GYRO_XYZ", "SENSOR_CHAN_MAGN_XYZ",
                   "SENSOR_CHAN_LIGHT", "SENSOR_CHAN_PROX", "SENSOR_CHAN_DISTANCE", "SENSOR_CHAN_VOLTAGE",
                   "SENSOR_CHAN_CURRENT", "SENSOR_CHAN_GAS_RES", "SENSOR_CHAN_CO2"]


# ---- devices of a draft ----------------------------------------------------------------------------
@dataclass
class Device:
    ident: str                      # C identifier part: "bme280_76"
    label: str                      # node label used in DT_NODELABEL()
    compatible: str
    cls: str                        # "sensor" | "led" | "generic"
    node_name: str = ""             # bme280@76
    parent: str = ""                # label of the draft node (bus) it sits in
    channels: list[str] = field(default_factory=list)       # SENSOR_CHAN_* (sensor only)


def c_ident(text: str) -> str:
    s = re.sub(r"[^a-zA-Z0-9]+", "_", text).strip("_").lower()
    return s if s and not s[0].isdigit() else f"n{s}"


def devices_from_draft(draft: Draft, channel_lookup=None) -> tuple[list[Device], list[str]]:
    """``(devices, notes)``. `channel_lookup(compatible) -> list of SENSOR_CHAN_*` supplies the default channels.

    Sensors: children (any depth) with a compatible of an I2C / SPI draft node. LEDs: children of a node whose
    compatible is ``gpio-leds``. Everything else with a compatible becomes a generic device. A device needs a
    node label (``DT_NODELABEL``); one without a label is left out and reported in `notes`.
    """
    out: list[Device] = []
    notes: list[str] = []
    seen: set[str] = set()

    def add(dev: Device) -> None:
        base, n = dev.ident, 2
        while dev.ident in seen:
            dev.ident, n = f"{base}_{n}", n + 1
        seen.add(dev.ident)
        out.append(dev)

    def visit(parent_label: str, parent_cls: str, parent_compat: str, ch: DraftChild) -> None:
        compat = ch.compatible[0] if ch.compatible else ""
        if compat or parent_compat == "gpio-leds":
            if not ch.labels:
                notes.append(f"{ch.node_name} has no node label: left out (DT_NODELABEL needs one)")
            else:
                label = ch.labels[0]
                if parent_compat == "gpio-leds":
                    cls = "led"
                elif compat and parent_cls in ("i2c", "spi"):
                    cls = "sensor"
                else:
                    cls = "generic"
                dev = Device(c_ident(label), label, compat or parent_compat, cls, ch.node_name, parent_label)
                if cls == "sensor":
                    dev.channels = list(channel_lookup(compat)) if channel_lookup else []
                add(dev)
        for sub in ch.children:
            visit(parent_label, parent_cls, compat, sub)

    for node in draft.nodes:
        for ch in node.children:
            visit(node.label or "", node.cls, node.compatible or "", ch)
    return out, notes


# ---- sensor channels from the driver source ---------------------------------------------------------
_FUNC_HEAD = re.compile(r"^[\w \t\*]*?\b(\w*channel_get\w*)\s*\(", re.M)
_CHAN = re.compile(r"\bSENSOR_CHAN_([A-Z0-9_]+)\b")


def _function_body(text: str, start: int) -> str:
    """Body of the function whose parameter list opens just before `start`; "" for a call or a prototype."""
    depth, j = 1, start
    while j < len(text) and depth:
        depth += {"(": 1, ")": -1}.get(text[j], 0)
        j += 1
    rest = text[j:].lstrip()
    if not rest.startswith("{"):
        return ""
    i = text.index("{", j)
    depth = 0
    for k in range(i, len(text)):
        if text[k] == "{":
            depth += 1
        elif text[k] == "}":
            depth -= 1
            if depth == 0:
                return text[i:k + 1]
    return text[i:]


def channels_from_driver(sources: list[str]) -> list[str]:
    """``SENSOR_CHAN_*`` named in the driver's ``*channel_get*`` function, in source order.

    Heuristic: the first function definition whose name contains ``channel_get`` and whose body names a channel
    (case labels or comparisons). Drivers that dispatch through helper functions yield an empty list; the user then
    picks the channels in the UI (``COMMON_CHANNELS``).
    """
    found: list[str] = []
    for text in sources:
        for m in _FUNC_HEAD.finditer(text):
            names = [n for n in _CHAN.findall(_function_body(text, m.end())) if n not in _NOT_CHANNELS]
            if names:
                found += [f"SENSOR_CHAN_{n}" for n in names]
                break
    return list(dict.fromkeys(found))


_HDR_COMPAT = re.compile(r"^\s*#\s*define\s+DT_DRV_COMPAT\s+(\w+)", re.M)
_hdr_cache: dict[tuple, dict[str, set[Path]]] = {}


def header_driver_dirs(dirs: list[Path]) -> dict[str, set[Path]]:
    """compatible identifier -> folders whose ``.h`` defines ``DT_DRV_COMPAT``.

    ``DriverIndex`` only sees ``.c`` files; some drivers (the Bosch sensors) define the compatible in a header
    next to the sources, so their ``.c`` files are found through this index. Cached per folder set.
    """
    key = tuple(str(d) for d in dirs)
    if key not in _hdr_cache:
        idx: dict[str, set[Path]] = {}
        for d in dirs:
            for h in Path(d).rglob("*.h"):
                try:
                    txt = h.read_text(encoding="utf-8", errors="ignore")
                except OSError:
                    continue
                if "DT_DRV_COMPAT" in txt:
                    for c in _HDR_COMPAT.findall(txt):
                        idx.setdefault(c, set()).add(h.parent.resolve())
        _hdr_cache[key] = idx
    return _hdr_cache[key]


def channel_field(channel: str) -> str:
    return c_ident(channel.removeprefix("SENSOR_CHAN_"))


# ---- files -----------------------------------------------------------------------------------------
def checksum(body: str) -> str:
    return hashlib.sha256(body.replace("\r\n", "\n").encode("utf-8")).hexdigest()[:16]


def with_header(body: str, kind: str) -> str:
    """`body` behind the generated-by line of its file type (``c`` or ``cmake``)."""
    body = body.replace("\r\n", "\n")
    tail = f"generated by dt_explorer (dtx_devices), checksum {checksum(body)}"
    first = (f"/* {tail} - edit the file and it is no longer overwritten */" if kind == "c"
             else f"# {tail} - edit the file and it is no longer overwritten")
    return first + "\n" + body


def header_state(text: str) -> str:
    """``"intact"`` (header present, checksum matches the body), ``"edited"`` (header, other body) or ``"foreign"``."""
    first, _, body = text.replace("\r\n", "\n").partition("\n")
    m = _HEADER_RX.match(first)
    if not m:
        return "foreign"
    return "intact" if m.group(1) == checksum(body) else "edited"


def _tmpl(name: str) -> Template:
    return Template((TEMPLATES / f"{name}.tmpl").read_text(encoding="utf-8"))


def _texts(d: Device) -> tuple[str, str]:
    sub = dict(id=d.ident, ID=d.ident.upper(), label=d.label, compatible=d.compatible)
    if d.cls == "sensor":
        chans = d.channels
        sub["channel_names"] = ", ".join(chans) or "none"
        sub["fields"] = "".join(f"\tstruct sensor_value {channel_field(c)};\t/* {c} */\n" for c in chans) \
            or "\tint unused;\t/* no channel selected */\n"
        sub["gets"] = "".join(f"\trc = sensor_channel_get(dev, {c}, &out->{channel_field(c)});\n"
                              f"\tif (rc != 0) {{\n\t\treturn rc;\n\t}}\n" for c in chans)
    return _tmpl(f"{d.cls}_h").substitute(sub), _tmpl(f"{d.cls}_c").substitute(sub)


def render_files(devices: list[Device]) -> dict[str, str]:
    """module-relative path (forward slashes) -> full file text with header."""
    files: dict[str, str] = {}
    srcs = ["src/dtx_devices.c"]
    incs, calls = [], []
    for d in devices:
        h, c = _texts(d)
        files[f"include/dtx_{d.ident}.h"] = with_header(h, "c")
        files[f"src/dtx_{d.ident}.c"] = with_header(c, "c")
        srcs.append(f"src/dtx_{d.ident}.c")
        incs.append(f'#include "dtx_{d.ident}.h"\n')
        calls.append(_tmpl("device_init_call").substitute(id=d.ident))
    files["include/dtx_devices.h"] = with_header(
        _tmpl("umbrella_h").substitute(includes=("\n" + "".join(incs)) if incs else ""), "c")
    files["src/dtx_devices.c"] = with_header(_tmpl("umbrella_c").substitute(calls="".join(calls)), "c")
    files["CMakeLists.txt"] = with_header(
        _tmpl("cmake").substitute(sources="".join(f"\t{s}\n" for s in srcs).rstrip("\n")), "cmake")
    return dict(sorted(files.items(), key=lambda kv: (kv[0] != "CMakeLists.txt", kv[0])))


# ---- plan / write ------------------------------------------------------------------------------------
def _lines(text: str) -> list[str]:
    """Lines with a newline each; a last line without one is followed by git's no-newline marker."""
    out = text.splitlines(keepends=True)
    if out and not out[-1].endswith(chr(10)):
        out[-1] += chr(10) + "\\ No newline at end of file" + chr(10)
    return out


def _udiff(old: str, new: str, a: str, b: str) -> str:
    return "".join(difflib.unified_diff(_lines(old), _lines(new), fromfile=a, tofile=b))


@dataclass
class GenFile:
    rel: str                        # path below dtx_devices/
    path: Path
    text: str                       # the new content
    state: str                      # new | unchanged | regenerate | edited | foreign
    diff: str = ""                  # on disk -> new (regenerate / edited / foreign)

    @property
    def writes(self) -> bool:
        return self.state in ("new", "regenerate")


@dataclass
class GenPlan:
    app_dir: Path
    devices: list[Device]
    files: list[GenFile] = field(default_factory=list)
    notes: list[str] = field(default_factory=list)
    stale: list[Path] = field(default_factory=list)         # generated files of devices no longer in the draft
    cmake_state: str = ""           # "present" | "missing" | "no_cmakelists"
    cmake_diff: str = ""
    cmake_new: str = ""
    kconfig: list[str] = field(default_factory=list)        # lines that the generated code needs

    @property
    def module_dir(self) -> Path:
        return self.app_dir / MODULE_DIR


def kconfig_for(devices: list[Device]) -> list[str]:
    """``CONFIG_*=y`` lines the generated code needs on top of the driver symbols."""
    lines = []
    if any(d.cls == "sensor" for d in devices):
        lines.append("CONFIG_SENSOR=y")
    if any(d.cls == "led" for d in devices):
        lines.append("CONFIG_GPIO=y")
    return lines


def plan_generate(app_dir: Path | str, devices: list[Device], notes: list[str] | None = None) -> GenPlan:
    """What :func:`write_files` would do. Reads the app folder, writes nothing."""
    app = Path(app_dir)
    plan = GenPlan(app, devices, notes=list(notes or []), kconfig=kconfig_for(devices))
    rendered = render_files(devices)
    for rel, text in rendered.items():
        path = plan.module_dir / rel
        if not path.is_file():
            plan.files.append(GenFile(rel, path, text, "new"))
            continue
        old = path.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n")
        hs = header_state(old)
        if old == text:
            plan.files.append(GenFile(rel, path, text, "unchanged"))
        elif hs == "intact":
            plan.files.append(GenFile(rel, path, text, "regenerate",
                                      _udiff(old, text, f"{rel} (on disk)", f"{rel} (regenerated)")))
        else:
            plan.files.append(GenFile(rel, path, text, "edited" if hs == "edited" else "foreign",
                                      _udiff(old, text, f"{rel} (on disk)", f"{rel} (would be generated)")))
    if plan.module_dir.is_dir():
        for p in sorted(plan.module_dir.rglob("*")):
            rel = p.relative_to(plan.module_dir).as_posix()
            if p.is_file() and rel not in rendered and header_state(p.read_text(encoding="utf-8", errors="replace")) != "foreign":
                plan.stale.append(p)
    cm = app / "CMakeLists.txt"
    if not cm.is_file():
        plan.cmake_state = "no_cmakelists"
    else:
        old = cm.read_text(encoding="utf-8", errors="replace").replace("\r\n", "\n")
        if re.search(r"^\s*add_subdirectory\(\s*dtx_devices\s*\)", old, re.M):
            plan.cmake_state = "present"
        else:
            plan.cmake_state = "missing"
            plan.cmake_new = old + ("" if old.endswith("\n") or not old else "\n") + CMAKE_LINE + "\n"
            plan.cmake_diff = _udiff(old, plan.cmake_new, "CMakeLists.txt (existing)", "CMakeLists.txt (with the line)")
    return plan


def write_files(plan: GenPlan) -> list[str]:
    """Write the ``new`` and ``regenerate`` files; ``edited`` / ``foreign`` ones are never touched. Returns report lines."""
    lines = []
    root = plan.module_dir.resolve()
    for f in plan.files:
        if root not in f.path.resolve().parents:
            raise ValueError(f"refusing to write outside {root}: {f.path}")
        if f.writes:
            f.path.parent.mkdir(parents=True, exist_ok=True)
            f.path.write_text(f.text, encoding="utf-8", newline="\n")
            lines.append(f"{'written' if f.state == 'new' else 'regenerated'}: {f.path}")
            log.info("codegen: %s %s", f.state, f.path)
        elif f.state == "unchanged":
            lines.append(f"unchanged:   {f.path}")
        else:
            lines.append(f"NOT written ({f.state}): {f.path}")
            log.warning("codegen: %s left alone (%s)", f.path, f.state)
    for p in plan.stale:
        lines.append(f"stale (device no longer in the draft, not deleted): {p}")
    return lines


def apply_cmake_line(plan: GenPlan) -> str:
    """Add ``add_subdirectory(dtx_devices)`` to the app's CMakeLists.txt, once. Call only after the user confirmed
    :attr:`GenPlan.cmake_diff`. Returns a report line."""
    cm = plan.app_dir / "CMakeLists.txt"
    if plan.cmake_state == "present":
        return f"CMakeLists.txt already has {CMAKE_LINE}; unchanged"
    if plan.cmake_state != "missing":
        return "no CMakeLists.txt in the app folder; nothing changed"
    cm.write_text(plan.cmake_new, encoding="utf-8", newline="\n")
    log.info("codegen: added %s to %s", CMAKE_LINE, cm)
    plan.cmake_state = "present"
    return f"added {CMAKE_LINE} to {cm}"
